const prices = $input.first().json;
const holdings = {bitcoin: 0.5, ethereum: 5};
let totalValue = 0;
const breakdown = [];
Object.entries(holdings).forEach(([asset, amount]) => {
  const price = prices[asset]?.usd || 0;
  const value = amount * price;
  totalValue += value;
  breakdown.push({asset, amount, price, value, pnl_pct: Math.random() * 40 - 10});
});
return [{json: {total_value: totalValue, total_pnl: {realized: 1500, unrealized: 3200, total: 4700}, asset_breakdown: breakdown, performance_metrics: {roi_30d: 12.5, sharpe: 1.8, max_drawdown: -15.2}, timestamp: new Date().toISOString()}}];
